parameters.jsCode:
const item = $input.item.json;
const tier = item.urgency_tier;
const days = item.days_until_due;

let subjectPrefix, urgencyLabel, bodyOpening;

if (tier === 'critical') {
  subjectPrefix = '[CRITICAL]';
  urgencyLabel = 'CRITICAL — Replacement required within 7 days';
  bodyOpening = 'IMMEDIATE ACTION REQUIRED: The following equipment must be replaced within 7 days to maintain compliance and operational safety.';
} else if (tier === 'urgent') {
  subjectPrefix = '[URGENT]';
  urgencyLabel = 'URGENT — Replacement required within 30 days';
  bodyOpening = 'Please begin procurement immediately. The following equipment is due for replacement within 30 days.';
} else {
  subjectPrefix = '[REMINDER]';
  urgencyLabel = 'REMINDER — Replacement required within 180 days';
  bodyOpening = 'This is your 6-month advance notice. The following equipment will require replacement within 180 days. Please begin long-lead procurement planning.';
}

return [{
  json: {
    ...item,
    subject_prefix: subjectPrefix,
    urgency_label: urgencyLabel,
    body_opening: bodyOpening
  }
}];

